// Measures what a runner gives a node_modules restore: download throughput with parallel range
// requests, and sequential disk writes. Packs and restores disk images in chunks that download
// and decompress in parallel. Dependency-free.
//
//   node net.ts download --url URL [--connections N[,N...]] [--chunk-mb M] [--out FILE] [--label TEXT]
//     Downloads URL (or the URL in the environment variable that --url-env names) with N
//     concurrent range requests of M MB, once per N, and discards the data unless --out is given.
//   node net.ts download-entry (--url-env NAME | --artifact-id ID) (--out-dir DIR | --out-file FILE) [--connections N]
//     Downloads the single file of an artifact zip, without downloading the zip.
//   node net.ts disk --file PATH [--mb N]
//     Writes N MB sequentially in 8 MB writes, then flushes them to the device.
//   node net.ts image-pack --in FILE --out FILE.nmbimg [--chunk-mb 32] [--level 19]
//     Compresses each chunk of FILE independently with zstd, without its pages of zeros.
//   node net.ts image-restore (--file FILE.nmbimg | --url-env NAME [--zip false] | --artifact-id ID) --out FILE [--connections 16] [--window 64] [--sparse true]
//     Recreates FILE from an image, an artifact zip that stores one, or a URL of the image itself:
//     downloads, decompresses and writes the chunks at the same time, in order.
//
// --artifact-id downloads an artifact of the repository in GITHUB_REPOSITORY with the token in NMB_TOKEN.

import { randomBytes } from 'crypto';
import * as fs from 'fs';
import * as os from 'os';
import { promisify } from 'util';
import * as zlib from 'zlib';

// Decompression runs in the thread pool of libuv, next to the file writes
process.env.UV_THREADPOOL_SIZE ??= String(Math.max(16, os.availableParallelism() * 2));

type Args = Map<string, string>;

function parseArgs(argv: readonly string[]): Args {
	const args: Args = new Map();
	for (let i = 0; i < argv.length; i += 2) {
		args.set(argv[i].replace(/^--/, ''), argv[i + 1]);
	}
	return args;
}

function report(result: Record<string, unknown>): void {
	const line = JSON.stringify(result);
	console.log(line);
	if (process.env.GITHUB_STEP_SUMMARY) {
		fs.appendFileSync(process.env.GITHUB_STEP_SUMMARY, `- \`${line}\`\n`);
	}
}

async function size(url: string): Promise<number> {
	const response = await fetch(url, { headers: { Range: 'bytes=0-0' } });
	const range = response.headers.get('content-range');
	await response.body?.cancel();
	if (response.status !== 206 || !range) {
		throw new Error(`No range support: HTTP ${response.status}`);
	}
	return Number(range.split('/')[1]);
}

async function fetchRange(url: string, from: number, to: number): Promise<Buffer> {
	for (let attempt = 1; ; attempt++) {
		try {
			const response = await fetch(url, { headers: { Range: `bytes=${from}-${to}` } });
			if (response.status !== 206) {
				throw new Error(`HTTP ${response.status}`);
			}
			return Buffer.from(await response.arrayBuffer());
		} catch (err) {
			if (attempt === 4) {
				throw err;
			}
		}
	}
}

async function download(args: Args): Promise<void> {
	const url = args.get('url') ?? process.env[args.get('url-env') ?? ''];
	if (!url) {
		report({ label: args.get('label'), error: 'no URL' });
		return;
	}
	const chunk = Number(args.get('chunk-mb') ?? '8') * 1024 * 1024;
	const out = args.get('out');
	const total = await size(url);
	for (const connections of (args.get('connections') ?? '8').split(',').map(Number)) {
		const handle = out ? await fs.promises.open(out, 'w') : undefined;
		const start = performance.now();
		try {
			await parallelDownload(url, 0, total, connections, chunk, handle);
		} finally {
			await handle?.close();
		}
		const seconds = (performance.now() - start) / 1000;
		report({ label: args.get('label'), connections, chunkMB: chunk / 1024 / 1024, MB: Math.round(total / 1e6), seconds: Number(seconds.toFixed(2)), MBps: Math.round(total / seconds / 1e6), toDisk: !!out });
	}
}

/** Downloads `length` bytes of `url` from `start` with concurrent range requests, into `handle` from its offset 0 */
async function parallelDownload(url: string, start: number, length: number, connections: number, chunk: number, handle: fs.promises.FileHandle | undefined): Promise<void> {
	const chunks = Math.ceil(length / chunk);
	let next = 0;
	await Promise.all(Array.from({ length: Math.min(connections, chunks) }, async () => {
		while (next < chunks) {
			const offset = next++ * chunk;
			const data = await fetchRange(url, start + offset, start + Math.min(length, offset + chunk) - 1);
			await handle?.write(data, 0, data.length, offset);
		}
	}));
}

/**
 * Downloads the single file of an artifact, which upload-artifact stores uncompressed in a zip
 * with compression-level 0, without the zip: a few small range requests find its data in the
 * central directory, which supports zip64, and then concurrent range requests download it.
 * --urls-env names an environment variable with a JSON array of URLs instead, to download several.
 */
async function downloadEntry(args: Args): Promise<void> {
	const urls: string[] = args.has('urls-env') ? JSON.parse(process.env[args.get('urls-env')!] ?? '[]') : [await sourceUrl(args)];
	for (const url of urls) {
		if (!url) {
			throw new Error('No URL');
		}
		await downloadOneEntry(url, args);
	}
}

/**
 * The URL of --url, of the environment variable that --url-env names, or of the zip of the
 * artifact --artifact-id of this repository, which the token in NMB_TOKEN can download. The
 * signed URL of an artifact expires after a minute, so it is resolved right before the download.
 */
async function sourceUrl(args: Args): Promise<string> {
	const id = args.get('artifact-id');
	if (!id) {
		return args.get('url') ?? process.env[args.get('url-env') ?? ''] ?? '';
	}
	const response = await fetch(`${process.env.GITHUB_API_URL ?? 'https://api.github.com'}/repos/${process.env.GITHUB_REPOSITORY}/actions/artifacts/${id}/zip`, {
		headers: { Authorization: `Bearer ${process.env.NMB_TOKEN}`, Accept: 'application/vnd.github+json' },
		redirect: 'manual',
	});
	await response.body?.cancel();
	const location = response.headers.get('location');
	if (!location) {
		throw new Error(`No download URL for artifact ${id}: HTTP ${response.status}`);
	}
	return location;
}

async function downloadOneEntry(url: string, args: Args): Promise<void> {
	const start = performance.now();
	const entry = await locateZipEntry(url);
	const outDir = args.get('out-dir') ?? '.';
	const out = args.get('out-file') ?? `${outDir}/${entry.name}`;
	fs.mkdirSync(out.replace(/[\\/][^\\/]*$/, '') || '.', { recursive: true });
	const connections = Number(args.get('connections') ?? '16');
	const handle = await fs.promises.open(out, 'w');
	try {
		await parallelDownload(url, entry.start, entry.size, connections, Number(args.get('chunk-mb') ?? '8') * 1024 * 1024, handle);
	} finally {
		await handle.close();
	}
	const seconds = (performance.now() - start) / 1000;
	report({ label: args.get('label') ?? entry.name, file: out, connections, MB: Math.round(entry.size / 1e6), seconds: Number(seconds.toFixed(2)), MBps: Math.round(entry.size / seconds / 1e6) });
}

interface ZipEntry {
	readonly name: string;
	/** The offset of the data of the entry in the zip */
	readonly start: number;
	readonly size: number;
}

/** Finds the data of the first entry of a zip that stores it uncompressed, with a few small range requests */
async function locateZipEntry(url: string): Promise<ZipEntry> {
	const total = await size(url);
	const tail = await fetchRange(url, Math.max(0, total - 65_600), total - 1);
	let eocd = -1;
	for (let i = tail.length - 22; i >= 0 && eocd === -1; i--) {
		if (tail.readUInt32LE(i) === 0x06054b50) {
			eocd = i;
		}
	}
	if (eocd === -1) {
		throw new Error('No end of central directory record');
	}
	let directorySize = tail.readUInt32LE(eocd + 12);
	let directoryOffset = tail.readUInt32LE(eocd + 16);
	if (directoryOffset === 0xffffffff || directorySize === 0xffffffff) {
		const locator = eocd - 20;
		if (tail.readUInt32LE(locator) !== 0x07064b50) {
			throw new Error('No zip64 end of central directory locator');
		}
		const record = await fetchRange(url, Number(tail.readBigUInt64LE(locator + 8)), Number(tail.readBigUInt64LE(locator + 8)) + 55);
		directorySize = Number(record.readBigUInt64LE(40));
		directoryOffset = Number(record.readBigUInt64LE(48));
	}
	const directory = await fetchRange(url, directoryOffset, directoryOffset + directorySize - 1);
	if (directory.readUInt32LE(0) !== 0x02014b50) {
		throw new Error('No central directory');
	}
	const method = directory.readUInt16LE(10);
	let compressedSize = directory.readUInt32LE(20);
	let uncompressedSize = directory.readUInt32LE(24);
	const nameLength = directory.readUInt16LE(28);
	const extraLength = directory.readUInt16LE(30);
	let localOffset = directory.readUInt32LE(42);
	const name = directory.toString('utf8', 46, 46 + nameLength);
	for (let extra = 46 + nameLength; extra + 4 <= 46 + nameLength + extraLength;) {
		const id = directory.readUInt16LE(extra);
		const fieldLength = directory.readUInt16LE(extra + 2);
		if (id === 0x0001) {
			let field = extra + 4;
			const next = () => {
				const value = Number(directory.readBigUInt64LE(field));
				field += 8;
				return value;
			};
			if (uncompressedSize === 0xffffffff) {
				uncompressedSize = next();
			}
			if (compressedSize === 0xffffffff) {
				compressedSize = next();
			}
			if (localOffset === 0xffffffff) {
				localOffset = next();
			}
		}
		extra += 4 + fieldLength;
	}
	if (method !== 0) {
		throw new Error(`${name} is compressed with method ${method}, not stored`);
	}
	const local = await fetchRange(url, localOffset, localOffset + 29);
	return { name, start: localOffset + 30 + local.readUInt16LE(26) + local.readUInt16LE(28), size: compressedSize };
}

//#region images

const IMAGE_MAGIC = Buffer.from('NMBIMG02');
/** The unit of the holes of an image: the pages of zeros are neither stored nor written */
const PAGE = 1024 * 1024;

interface ImageHeader {
	readonly rawSize: number;
	readonly chunkSize: number;
	readonly level: number;
	/** For each chunk, the size of its zstd frame and the bit mask of its pages that are not zeros, which the frame holds in order */
	readonly chunks: readonly (readonly [size: number, pages: number])[];
}

const zstdCompress = promisify(zlib.zstdCompress);
const zstdDecompress = promisify(zlib.zstdDecompress);
/** Larger output buffers than the default of 16 KB, which would take a trip to the thread pool each */
const ZLIB_CHUNK = 4 * 1024 * 1024;

async function writeAll(handle: fs.promises.FileHandle, data: Buffer, position: number): Promise<void> {
	for (let offset = 0; offset < data.length;) {
		const { bytesWritten } = await handle.write(data, offset, data.length - offset, position + offset);
		offset += bytesWritten;
	}
}

async function readAll(handle: fs.promises.FileHandle, length: number, position: number): Promise<Buffer> {
	const buffer = Buffer.allocUnsafe(length);
	for (let offset = 0; offset < length;) {
		const { bytesRead } = await handle.read(buffer, offset, length - offset, position + offset);
		if (bytesRead === 0) {
			throw new Error(`Unexpected end of file at ${position + offset}`);
		}
		offset += bytesRead;
	}
	return buffer;
}

/** The runs of consecutive set bits of a page mask, as [first page, page count] */
function pageRuns(mask: number, pages: number): [number, number][] {
	const runs: [number, number][] = [];
	for (let page = 0; page < pages; page++) {
		if (mask & (1 << page)) {
			const last = runs[runs.length - 1];
			if (last && last[0] + last[1] === page) {
				last[1]++;
			} else {
				runs.push([page, 1]);
			}
		}
	}
	return runs;
}

async function imagePack(args: Args): Promise<void> {
	const start = performance.now();
	const input = args.get('in')!;
	const output = args.get('out')!;
	const chunkSize = Number(args.get('chunk-mb') ?? '32') * 1024 * 1024;
	if (chunkSize > 32 * PAGE || chunkSize % PAGE) {
		throw new Error('The chunks hold at most 32 pages of 1 MB');
	}
	const level = Number(args.get('level') ?? '19');
	const concurrency = Number(args.get('concurrency') ?? String(os.availableParallelism()));
	const rawSize = fs.statSync(input).size;
	const count = Math.ceil(rawSize / chunkSize);
	const frames: (Buffer | undefined)[] = new Array(count);
	const masks: number[] = new Array(count).fill(0);
	const zeros = Buffer.alloc(PAGE);
	const options: zlib.ZstdOptions = { chunkSize: ZLIB_CHUNK, params: { [zlib.constants.ZSTD_c_compressionLevel]: level, [zlib.constants.ZSTD_c_checksumFlag]: 1 } };
	const handle = await fs.promises.open(input, 'r');
	let next = 0;
	let storedBytes = 0;
	try {
		await Promise.all(Array.from({ length: concurrency }, async () => {
			while (next < count) {
				const index = next++;
				const raw = await readAll(handle, Math.min(chunkSize, rawSize - index * chunkSize), index * chunkSize);
				const pages: Buffer[] = [];
				for (let page = 0; page * PAGE < raw.length; page++) {
					const data = raw.subarray(page * PAGE, (page + 1) * PAGE);
					if (!data.equals(zeros.subarray(0, data.length))) {
						masks[index] |= 1 << page;
						pages.push(data);
					}
				}
				if (pages.length) {
					const data = pages.length === raw.length / PAGE ? raw : Buffer.concat(pages);
					storedBytes += data.length;
					frames[index] = await zstdCompress(data, options);
				}
			}
		}));
	} finally {
		await handle.close();
	}
	const header: ImageHeader = { rawSize, chunkSize, level, chunks: Array.from({ length: count }, (_, index) => [frames[index]?.length ?? 0, masks[index] >>> 0]) };
	const json = Buffer.from(JSON.stringify(header));
	const prefix = Buffer.alloc(IMAGE_MAGIC.length + 4);
	IMAGE_MAGIC.copy(prefix);
	prefix.writeUInt32LE(json.length, IMAGE_MAGIC.length);
	const out = await fs.promises.open(output, 'w');
	try {
		let position = 0;
		for (const part of [prefix, json, ...frames]) {
			if (part) {
				await writeAll(out, part, position);
				position += part.length;
			}
		}
	} finally {
		await out.close();
	}
	const seconds = (performance.now() - start) / 1000;
	const compressed = header.chunks.reduce((sum, [length]) => sum + length, 0);
	report({ label: 'image-pack', file: output, rawMB: Math.round(rawSize / 1e6), storedMB: Math.round(storedBytes / 1e6), MB: Math.round(compressed / 1e6), chunks: count, zeroChunks: header.chunks.filter(([length]) => !length).length, level, seconds: Number(seconds.toFixed(2)) });
}

/** Reads ranges of a packed image, from a local file, from a URL, or from the stored entry of an artifact zip at a URL */
interface ImageSource {
	readonly size: number;
	read(from: number, length: number): Promise<Buffer>;
	close(): Promise<void>;
}

async function openImageSource(args: Args): Promise<ImageSource> {
	const file = args.get('file');
	if (file) {
		const handle = await fs.promises.open(file, 'r');
		return { size: (await handle.stat()).size, read: (from, length) => readAll(handle, length, from), close: () => handle.close() };
	}
	const url = await sourceUrl(args);
	if (!url) {
		throw new Error('No --file and no URL');
	}
	const { start, size: length } = args.get('zip') === 'false' ? { start: 0, size: await size(url) } : await locateZipEntry(url);
	return { size: length, read: (from, count) => fetchRange(url, start + from, start + from + count - 1), close: async () => { } };
}

async function imageRestore(args: Args): Promise<void> {
	const start = performance.now();
	const out = args.get('out')!;
	const connections = Number(args.get('connections') ?? '16');
	const window = Number(args.get('window') ?? '64');
	// Holes instead of the chunks of zeros, where a disk image file can be sparse
	const sparse = (args.get('sparse') ?? String(process.platform !== 'win32')) === 'true';
	const source = await openImageSource(args);
	let head = await source.read(0, Math.min(source.size, 1024 * 1024));
	if (!head.subarray(0, IMAGE_MAGIC.length).equals(IMAGE_MAGIC)) {
		throw new Error('Not a packed image');
	}
	const headerEnd = IMAGE_MAGIC.length + 4 + head.readUInt32LE(IMAGE_MAGIC.length);
	if (headerEnd > head.length) {
		head = await source.read(0, headerEnd);
	}
	const header: ImageHeader = JSON.parse(head.toString('utf8', IMAGE_MAGIC.length + 4, headerEnd));
	const headerSeconds = (performance.now() - start) / 1000;
	const offsets: number[] = [];
	let offset = headerEnd;
	for (const [length] of header.chunks) {
		offsets.push(offset);
		offset += length;
	}
	const count = header.chunks.length;
	const ready = new Map<number, Buffer | undefined>();
	let next = 0;
	let written = 0;
	let wakeWriter: (() => void) | undefined;
	let wakeWorkers: (() => void)[] = [];
	let downloadSeconds = 0;
	let decompressSeconds = 0;
	let writeSeconds = 0;
	let writerIdleSeconds = 0;
	let writtenBytes = 0;
	const worker = async () => {
		while (next < count) {
			const index = next++;
			// Bounds the memory to the chunks of the window
			while (index >= written + window) {
				await new Promise<void>(resolve => wakeWorkers.push(resolve));
			}
			let data: Buffer | undefined;
			const [length] = header.chunks[index];
			if (length > 0) {
				let time = performance.now();
				const frame = await source.read(offsets[index], length);
				downloadSeconds += (performance.now() - time) / 1000;
				time = performance.now();
				data = await zstdDecompress(frame, { chunkSize: ZLIB_CHUNK });
				decompressSeconds += (performance.now() - time) / 1000;
			}
			ready.set(index, data);
			wakeWriter?.();
		}
	};
	const handle = await fs.promises.open(out, 'w');
	const writer = async () => {
		for (let index = 0; index < count; index++) {
			let time = performance.now();
			while (!ready.has(index)) {
				await new Promise<void>(resolve => wakeWriter = resolve);
			}
			wakeWriter = undefined;
			writerIdleSeconds += (performance.now() - time) / 1000;
			const data = ready.get(index);
			ready.delete(index);
			const position = index * header.chunkSize;
			const length = Math.min(header.chunkSize, header.rawSize - position);
			const runs = pageRuns(header.chunks[index][1], Math.ceil(length / PAGE));
			const pageBytes = (page: number, pages: number) => Math.min(pages * PAGE, length - page * PAGE);
			const stored = runs.reduce((sum, [page, pages]) => sum + pageBytes(page, pages), 0);
			if ((data?.length ?? 0) !== stored) {
				throw new Error(`Chunk ${index} has ${data?.length ?? 0} bytes instead of ${stored}`);
			}
			time = performance.now();
			if (sparse) {
				let from = 0;
				for (const [page, pages] of runs) {
					const bytes = pageBytes(page, pages);
					await writeAll(handle, data!.subarray(from, from + bytes), position + page * PAGE);
					from += bytes;
					writtenBytes += bytes;
				}
			} else {
				let chunk = data;
				if (stored !== length) {
					chunk = Buffer.alloc(length);
					let from = 0;
					for (const [page, pages] of runs) {
						const bytes = pageBytes(page, pages);
						data!.copy(chunk, page * PAGE, from, from + bytes);
						from += bytes;
					}
				}
				await writeAll(handle, chunk!, position);
				writtenBytes += length;
			}
			writeSeconds += (performance.now() - time) / 1000;
			written = index + 1;
			const waiting = wakeWorkers;
			wakeWorkers = [];
			waiting.forEach(resolve => resolve());
		}
		await handle.truncate(header.rawSize);
	};
	try {
		await Promise.all([writer(), ...Array.from({ length: connections }, worker)]);
	} finally {
		await handle.close();
		await source.close();
	}
	const seconds = (performance.now() - start) / 1000;
	const compressed = header.chunks.reduce((sum, [length]) => sum + length, 0);
	report({
		label: args.get('label') ?? 'image-restore', file: out, rawMB: Math.round(header.rawSize / 1e6), writtenMB: Math.round(writtenBytes / 1e6), MB: Math.round(compressed / 1e6), chunks: count, zeroChunks: header.chunks.filter(([length]) => !length).length,
		connections, window, sparse, seconds: Number(seconds.toFixed(2)), writtenMBps: Math.round(writtenBytes / seconds / 1e6), MBps: Math.round(compressed / seconds / 1e6), headerSeconds: Number(headerSeconds.toFixed(2)),
		// Summed over the workers: how long they waited for the network and the thread pool
		downloadSeconds: Number(downloadSeconds.toFixed(2)), decompressSeconds: Number(decompressSeconds.toFixed(2)),
		writeSeconds: Number(writeSeconds.toFixed(2)), writerIdleSeconds: Number(writerIdleSeconds.toFixed(2)),
	});
}

//#endregion

async function disk(args: Args): Promise<void> {
	const file = args.get('file')!;
	const megabytes = Number(args.get('mb') ?? '4096');
	const buffer = randomBytes(8 * 1024 * 1024);
	const handle = await fs.promises.open(file, 'w');
	const start = performance.now();
	for (let written = 0; written < megabytes; written += 8) {
		await handle.write(buffer, 0, buffer.length);
	}
	const writeSeconds = (performance.now() - start) / 1000;
	await handle.sync();
	const totalSeconds = (performance.now() - start) / 1000;
	await handle.close();
	fs.rmSync(file);
	report({ label: 'disk', file, MB: megabytes, bufferedMBps: Math.round(megabytes / writeSeconds), withFlushMBps: Math.round(megabytes / totalSeconds), writeSeconds: Number(writeSeconds.toFixed(2)), totalSeconds: Number(totalSeconds.toFixed(2)) });
}

const [command, ...rest] = process.argv.slice(2);
const commands: Record<string, (args: Args) => Promise<void>> = { download, 'download-entry': downloadEntry, disk, 'image-pack': imagePack, 'image-restore': imageRestore };
const main = commands[command];
if (!main) {
	console.error(`Usage: node net.ts ${Object.keys(commands).join('|')} ...`);
	process.exit(1);
}
main(parseArgs(rest)).catch(err => {
	console.error(err);
	process.exit(1);
});
